If~$p \ge \frac34$, then~$\nu_p$ dominates a   Bernoulli product measure $\pi_{\theta_2(p)}$ with parameter
\begin{equation}
\theta_2(p) := 1 - \left(\frac{1-p + \sqrt{1-p}}{p} \right)^2.
 \end{equation}

Let us fix~$d \geq 1$ and~$\lambda > 1$. There exist~$R_{* \hspace{-.05cm} *} >0$ and~$\gamma > 0$ (that only depend on $d$ and $\lambda$) such that the following holds for any~$R \ge R_{* \hspace{-.05cm} *}$. Let~$\xi$ be a random configuration sampled from~${\mu}_{\lambda,R}$, and let~$\omega_\xi$ be the corresponding configuration of good boxes, as in~(23). Then the law of~$\omega_\xi$ stochastically dominates a Bernoulli product  measure with density~$1 - \exp(-\gamma R^d)$.

Let $\kappa, \alpha,  R_{*},  c$
  be as in Proposition~3.1, and assume~$R \ge R_*$. Let~$\xi$ be a random configuration sampled from~$\mu_{\lambda,R}$, and let~$\omega_\xi$ be the corresponding configuration of good boxes, as in~(23). Then the law of $\omega_\xi$ stochastically dominates~$\nu_{\theta_1(R)}$, where
\begin{equation}
\theta_1(R) := \left(1-\exp\left\{-\frac{c}{3}R^d\right\}\right)^2.
\end{equation}

Let~$\kappa, \alpha,  R_{*},  c$ and~$T$ be as in Proposition~3.1. Assume~$R \ge R_*$ and~$\xi_0 \in \{0,1\}^{\mathbb{Z}^d}$. Let~$(\xi_t)_{t \geq 0}$ be the contact process with infection rate $\lambda$ and range~$R$ started from~$\xi_0$, and let~$(\eta_n)_{n \ge 0}$ be the process of Definition 3.5 with~$p = \theta_1(R)$ (cf.\ (25)) and started from~$\eta_0 = \omega_{\xi_0}$. Then the law of $\omega_{\xi_T}$ stochastically dominates the law of $\eta_1$.

Let us fix~$d \geq 1$ and~$\lambda > 1$. There exist constants
$$\kappa \in \mathbb{N},\quad 0<\alpha<1,\quad  R_{*} > 0, \quad 0<T <\infty,\quad 0< c <\infty$$
(that only depend on $d$ and $\lambda$) such that the following holds  for any $R \geq R_*$.
Let
\begin{equation}

B = [0,\kappa R)^d,\quad B'= B+ \kappa R \cdot \vec{e}_1, \quad \widehat{B} = B \cup B',
\end{equation}
where~$\vec{e}_1=(1,0,\dots,0)$ is the first canonical vector of~$\mathbb{Z}^d$.

Let~$({\xi}_t)_{t \geq 0}$ be the contact process with infection rate $\lambda$ and range~$R$ on~$\widehat{B}$. If
\begin{equation}

|\xi_0 \cap ([0,R)^d + R \cdot z)| \geq \alpha R^d \text{ for all $z \in \mathbb{Z}^d$ such that } [0,R)^d +R \cdot z \subset B,
\end{equation}
then
$$
\mathbb{P}\left(\begin{array}{c}
|\xi_{T} \cap ([0,R)^d + R \cdot z) | \geq \alpha R^d\text{ for all }
\\
 z \in \mathbb{Z}^d \text { such that } [0,R)^d +R \cdot z \subset \widehat{B}
\end{array}\right) > 1-\exp\left( -c R^d \right).
$$

There exists~$\delta_0=\delta_0(d)  > 0$ such that the following holds for any~$R \geq 2$ and $\lambda>1$. Let
$$A = [0, \lfloor  R/2 \rfloor )^d,\qquad  A' = A +  u,\qquad  \widehat{A} = A \cup A',$$
where~$u \in \mathbb{Z}^d$ is chosen so that $\max_{x \in A,\; y \in A'} |x-y| \leq R$. Then, letting~$(\xi_t)_{t \geq 0}$ denote the contact process on~$\widehat{A}$ and
$m = |\xi_0 \cap A|$, we have
\begin{equation}
\mathbb{P}\left(|\xi_1 \cap A'| > \delta_0 m \right) \ge 1-\exp\left(- \delta_0 m\right), \qquad m \geq 2.
\end{equation}

There exists~$\delta > 0$ and~$m_0 > 0$ (that only depend on $d$ and $\lambda$) such that the following holds. Let~$R > 1$ and
\begin{equation}
B = [0,\kappa R)^d,\qquad B' = B + \kappa R \cdot \vec{e}_1,\qquad \widehat{B} = B \cup B',
\end{equation}
where~$\vec{e}_1$ denotes the first canonical vector. Let~$(\xi_t)$ be the contact process on~$\widehat{B}$ with infection rate $\lambda$ and range~$R$. If~$m := |\xi_0| \geq m_0$, then
\begin{equation}
  \mathbb{P}\left(\begin{array}{l}
|\xi_{(4\kappa)^d} \cap ([0,R)^d + R\cdot z )| \geq \delta m \text{ for } \\[.15cm] \text{all~$z \in \mathbb{Z}^d$ such that } [0,R)^d + R\cdot z \subset \widehat{B}
\end{array}\right) > 1-\exp(-\delta m).
\end{equation}

There exist constants
\begin{equation}
 \bar{R} > 0,\quad \alpha \in (0,1),\quad T_0 > 0, \quad c_0 > 0
 \end{equation}
(that only depend on $d$ and $\lambda$) such that the following holds  for any~$R \geq \bar{R}$. Letting~$B = [0,\kappa R)^d$ and~$(\xi_t)$ be the contact process on~$B$ with infection rate~$\lambda$, range~$R$ and initial configuration satisfying~$|\xi_0| \geq \alpha R^d$, we have
\begin{equation}
\mathbb{P}\left(|\xi_{T_0}| \geq \delta^{-1} \cdot \alpha  R^d\right) > 1 - \exp(-c_0 R^d),
\end{equation}
where~$\delta$ is the constant of Lemma~3.12.

We have~$\min_{0 \leq u \leq \kappa } a(u) > 0$.

There exists~$R_\diamond = R_\diamond(d,\lambda)$ such that for any~$R \ge R_\diamond$ we have~$Ph\geq (1-\frac{1}{\kappa})^d h$, that is,
\begin{equation}

 \frac{1}{|B(R)|}\cdot \sum_{y \in B \cap B(x,R)}\;h(y)\geq \left(1-\frac{1}{\kappa}\right)^d   h(x)\quad \text{for every~$x \in B$}.
 \end{equation}

If~$R \ge R_\diamond$  and~$\xi \in \{0,1\}^B$ satisfies~$|\xi| \leq \beta R^d$, then for any~$x \in B$ we have
\begin{equation}
\frac{\lambda}{|B(R)|} \cdot \sum_{y \in B \cap B(x,R)}  (1-\xi(y))\cdot g(y) > \frac{1+ \lambda}{2} \cdot g(x).
\end{equation}

For all~$t \geq 0$ the following statements hold.
\begin{enumerate}[(i)]
\item  We have
\begin{equation}
\left. \frac{d}{ds} \mathbb{E}\left[ e^{\varepsilon N_{t+s}} | \mathscr{F}_t\right] \right|_{s = 0} \leq 2 \varepsilon (\lambda - 1)\cdot  N_t \cdot e^{\varepsilon N_t}.
\end{equation}
\item For all $R \geq R_\diamond$, on the event
$\left\{ N_t \leq \beta R^d \right\}$,  we have
\begin{equation}
\left. \frac{d}{ds} \mathbb{E}\left[ e^{- \varepsilon X_{t+s}} | \mathscr{F}_t\right] \right|_{s = 0}  \leq -\frac{\varepsilon (\lambda - 1)}{4}\cdot X_t \cdot e^{-\varepsilon X_t}.
\end{equation}
\end{enumerate}

If we define $R_\diamond$, $T_0$, $\alpha$, $\tau$, $(U_t)$ and $(V_t)$ as above and
assume~$|\xi_0| = \lfloor \alpha R^d \rfloor$, then for any $R \geq R_\diamond$
 \begin{equation}
 (U_{t \wedge \tau})_{0 \leq t \leq {T_0}}\; \text{and}\; (V_{t \wedge \tau})_{0 \leq t \leq {T_0}} \;  \text{are supermartingales w.r.t. }(\mathscr{F}_t)_{ 0 \leq t \leq {T_0}}.
 \end{equation}
